nectPoint"]=0,["name"]=[[绿洲]],["permission"]=1,["fullName"]=[[绿洲(fb49_11)]],["enterable"]=1,["up"]=[[fb49_03]],["dsc"]=[[茫茫戈壁中的一块绿洲。绿草如茵，鲜花盛放。越靠中心处，植物越茂盛。最中心处，树木参天，百花齐绽，一派生机勃勃的景象。]],["down"]=[[fb49_20]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc201x]],["canLeave"]=1,["id"]=[[fb49_11]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[沙漠泉]],["permission"]=1,["left"]=[[fb49_11]],["enterable"]=1,["dsc"]=[[沙漠中的一抹清泉，清冽甘甜。西北常年缺水，号称“滴水贵如油”。如此清泉出现沙漠之中，实为上天的恩赐。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[沙漠泉(fb49_12)]],["canLeave"]=1,["id"]=[[fb49_12]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb49_14]],["connectPoint"]=0,["name"]=[[山路]],["permission"]=1,["fullName"]=[[山路(fb49_13)]],["enterable"]=1,["dsc"]=[[以碎石铺就的山路，层层石阶曲折迂回。路两侧黄土累累杂草丛生，平日里偶有鸟兽踪迹，却少有人烟。]],["down"]=[[fb49_21]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc201p]],["canLeave"]=1,["id"]=[[fb49_13]],["mapHide"]=0},{["operations"]={},["unit1"]=[[npc201q]],["stepMusic"]=[[jiaobu]],["right"]=[[fb49_15]],["connectPoint"]=0,["name"]=[[山路]],["permission"]=1,["left"]=[[fb49_13]],["enterable"]=1,["dsc"]=[[以碎石铺就的山路，层层石阶曲折迂回。路两侧黄土累累杂草丛生，平日里偶有鸟兽踪迹，却少有人烟。]],["fullName"]=[[山路(fb49_14)]],["visible"]=1,["dirIndex"]=0,["leftUp"]=[[fb49_07]],["canLeave"]=1,["id"]=[[fb49_14]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb49_16]],["connectPoint"]=0,["name"]=[[山脚]],["permission"]=1,["left"]=[[fb49_14]],["enterable"]=1,["dsc"]=[[此处是高山的山脚，向西方攀登则可以走上登峰的山路，向东则会步入漫漫的戈壁之中。]],["fullName"]=[[山脚(fb49_15)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc201t]],["unit1"]=[[npc201o]],["canLeave"]=1,["id"]=[[fb49_15]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb49_17]],["connectPoint"]=0,["name"]=[[戈壁]],["permission"]=1,["left"]=[[fb49_15]],["enterable"]=1,["dsc"]=[[广阔无垠的大戈壁。黄土蔓延，地面被粗沙、砾石所覆盖，几乎寸草不生，偶尔有一两棵枯树挺立其中。烈日炎炎之时，举目远望，则远方景物会出现变形。]],["fullName"]=[[戈壁(fb49_16)]],["visible"]=1,["dirIndex"]=0,["leftUp"]=[[fb49_08]],["canLe